import{_ as p,a0 as o,w as d,s as r,I as t,x as i,a1 as a,A as l,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"怎樣在 Ubuntu Linux 上安裝 MySQL | LCTT x X-CMD","titleTemplate":false,"description":"怎樣在 Ubuntu Linux 上安裝 MySQL | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣在 Ubuntu Linux 上安裝 MySQL | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣在 Ubuntu Linux 上安裝 MySQL | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20190416 How to Install MySQL in Ubuntu Linux","title":"怎樣在 Ubuntu Linux 上安裝 MySQL","tag":"201904","desc":""},"relativePath":"201904/20190416 How to Install MySQL in Ubuntu Linux.md","filePath":"[post].md"}'),u={name:"201904/20190416 How to Install MySQL in Ubuntu Linux.md"};function h(g,s,b,k,y,m){const e=o("Link");return d(),r("div",null,[s[28]||(s[28]=t("h1",{id:"怎樣在-ubuntu-linux-上安裝-mysql",tabindex:"-1"},[i("怎樣在 Ubuntu Linux 上安裝 MySQL "),t("a",{class:"header-anchor",href:"#怎樣在-ubuntu-linux-上安裝-mysql","aria-label":"Permalink to “怎樣在 Ubuntu Linux 上安裝 MySQL”"},"​")],-1)),s[29]||(s[29]=t("blockquote",null,[t("p",null,"本教程教你如何在基於 Ubuntu 的 Linux 發行版上安裝 MySQL。對於首次使用的用户，你將會學習到如何驗證你的安裝和第一次怎樣去連接 MySQL。")],-1)),t("p",null,[a(e,{href:"https://www.mysql.com/"},{default:l(()=>[...s[0]||(s[0]=[i("MySQL",-1)])]),_:1}),s[2]||(s[2]=i(" 是一個典型的資料庫管理系統。它被用於許多技術棧中，包括流行的 ",-1)),a(e,{href:"https://en.wikipedia.org/wiki/LAMP_(software_bundle)"},{default:l(()=>[...s[1]||(s[1]=[i("LAMP",-1)])]),_:1}),s[3]||(s[3]=i(" （Linux、Apache、MySQL、PHP）技術棧。它已經被證實了其穩定性。另一個讓 MySQL 受歡迎的原因是它是開源的。",-1))]),s[30]||(s[30]=n('<p>MySQL 是關係型資料庫（基本上是表格數據）。以這種方式它很容易去存儲、組織和訪問數據。它使用SQL（結構化查詢語言）來管理數據。</p><p>這這篇文章中，我將向你展示如何在 Ubuntu 18.04 安裝和使用 MySQL 8.0。讓我們一起來看看吧！</p><h3 id="在-ubuntu-上安裝-mysql" tabindex="-1">在 Ubuntu 上安裝 MySQL <a class="header-anchor" href="#在-ubuntu-上安裝-mysql" aria-label="Permalink to “在 Ubuntu 上安裝 MySQL”">​</a></h3><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/04/install-mysql-ubuntu.png?resize=800%2C450&amp;ssl=1" alt=""></p><p>我將會介紹兩種在 Ubuntu 18.04 上安裝 MySQL 的方法：</p><ol><li>從 Ubuntu 倉庫上安裝 MySQL。非常簡單，但不是最新版（5.7）</li><li>從官方倉庫安裝 MySQL。你將額外增加一些步處理過程，但不用擔心。你將會擁有最新版的MySQL（8.0）</li></ol><p>有必要的時候，我將會提供屏幕截圖去引導你。但這篇文章中的大部分步驟，我將直接在終端（默認熱鍵： <code>CTRL+ALT+T</code>）輸入命令。別害怕！</p><h4 id="方法-1、從-ubuntu-倉庫安裝-mysql" tabindex="-1">方法 1、從 Ubuntu 倉庫安裝 MySQL <a class="header-anchor" href="#方法-1、從-ubuntu-倉庫安裝-mysql" aria-label="Permalink to “方法 1、從 Ubuntu 倉庫安裝 MySQL”">​</a></h4><p>首先，輸入下列命令確保你的倉庫已經被更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>現在，安裝 MySQL 5.7，簡單輸入下列命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install mysql-server -y</span></span></code></pre></div><p>就是這樣！簡單且高效。</p><h4 id="方法-2、使用官方倉庫安裝-mysql" tabindex="-1">方法 2、使用官方倉庫安裝 MySQL <a class="header-anchor" href="#方法-2、使用官方倉庫安裝-mysql" aria-label="Permalink to “方法 2、使用官方倉庫安裝 MySQL”">​</a></h4><p>雖然這個方法多了一些步驟，但我將逐一介紹，並嘗試寫下清晰的筆記。</p>',15)),t("p",null,[s[5]||(s[5]=i("首先瀏覽 MySQL 官方網站的",-1)),a(e,{href:"https://dev.mysql.com/downloads/repo/apt/"},{default:l(()=>[...s[4]||(s[4]=[i("下載頁面",-1)])]),_:1}),s[6]||(s[6]=i("。",-1))]),s[31]||(s[31]=t("p",null,[t("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_apt_download_page.jpg?fit=800%2C280&ssl=1",alt:""})],-1)),s[32]||(s[32]=t("p",null,"在這裏，選擇 DEB 軟件包，點擊“Download”鏈接。",-1)),s[33]||(s[33]=t("p",null,[t("img",{src:"https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_deb_download_link.jpg?fit=800%2C507&ssl=1",alt:""})],-1)),s[34]||(s[34]=t("p",null,"滑到有關於 Oracle 網站信息的底部，右鍵 “No thanks, just start my download.”，然後選擇 “Copy link location”。",-1)),t("p",null,[s[8]||(s[8]=i("現在回到終端，我們將使用 ",-1)),a(e,{href:"https://linuxhandbook.com/curl-command-examples/"},{default:l(()=>[...s[7]||(s[7]=[i("Curl",-1)])]),_:1}),s[9]||(s[9]=i(" 命令去下載這個軟件包：",-1))]),s[35]||(s[35]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>curl -OL https://dev.mysql.com/get/mysql-apt-config_0.8.12-1_all.deb</span></span></code></pre></div><p><code>https://dev.mysql.com/get/mysql-apt-config_0.8.12-1_all.deb</code> 是我剛剛從網頁上覆制的鏈接。根據當前的 MySQL 版本，它有可能不同。讓我們使用 <code>dpkg</code> 去開始安裝 MySQL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dpkg -i mysql-apt-config*</span></span></code></pre></div><p>更新你的倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>要實際安裝 MySQL，我們將使用像第一個方法中同樣的命令來安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install mysql-server -y</span></span></code></pre></div><p>這樣做會在你的終端中打開包配置的提示。使用向下箭頭選擇“Ok”選項。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_package_configuration_ok.jpg?fit=800%2C587&amp;ssl=1" alt=""></p>',9)),t("p",null,[s[11]||(s[11]=i("點擊回車。這應該會提示你輸入密碼：這是在為 MySQL 設置 root 密碼。不要與 ",-1)),a(e,{href:"https://itsfoss.com/change-password-ubuntu/"},{default:l(()=>[...s[10]||(s[10]=[i("Ubuntu 的 root 密碼混淆",-1)])]),_:1}),s[12]||(s[12]=i("。",-1))]),s[36]||(s[36]=n('<p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_enter_password.jpg?fit=800%2C583&amp;ssl=1" alt=""></p><p>輸入密碼然後點擊 Tab 鍵去選擇“Ok“。點擊回車鍵，你將重新輸入密碼。操作完之後，再次鍵入 Tab 去選擇 “Ok”。按下回車鍵。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_information_on_configuring.jpg?fit=800%2C581&amp;ssl=1" alt=""></p><p>將會展示一些關於 MySQL Server 的配置信息。再次按下 Tab 去選擇 “Ok” 和按下回車鍵：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_default_authentication_plugin.jpg?fit=800%2C586&amp;ssl=1" alt=""></p><p>這裏你需要去選擇默認驗證插件。確保選擇了“Use Strong Password Encryption”。按下 Tab 鍵和回車鍵。</p><p>就是這樣！你已經成功地安裝了 MySQL。</p><h4 id="驗證你的-mysql-安裝" tabindex="-1">驗證你的 MySQL 安裝 <a class="header-anchor" href="#驗證你的-mysql-安裝" aria-label="Permalink to “驗證你的 MySQL 安裝”">​</a></h4><p>要驗證 MySQL 已經正確安裝，使用下列命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl status mysql.service</span></span></code></pre></div><p>這將展示一些關於 MySQL 服務的信息：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_service_information.jpg?fit=800%2C402&amp;ssl=1" alt=""></p><p>你應該在那裏看到 “Active: active (running)”。如果你沒有看到，使用下列命令去開始這個服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl start mysql.service</span></span></code></pre></div><h4 id="配置-保護-mysql" tabindex="-1">配置/保護 MySQL <a class="header-anchor" href="#配置-保護-mysql" aria-label="Permalink to “配置/保護 MySQL”">​</a></h4><p>對於剛安裝的 MySQL，你應該運行它提供的安全相關的更新命令。就是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mysql_secure_installation</span></span></code></pre></div><p>這樣做首先會詢問你是否想使用 “<ruby>密碼有效強度<rt>validate password component</rt></ruby>”。如果你想使用它，你將必須選擇一個最小密碼強度（0 – 低，1 – 中，2 – 高）。你將無法輸入任何不遵守所選規則的密碼。如果你沒有使用強密碼的習慣（本應該使用），這可能會配上用場。如果你認為它可能有幫助，那你就鍵入 <code>y</code> 或者 <code>Y</code>，按下回車鍵，然後為你的密碼選擇一個強度等級和輸入一個你想使用的密碼。如果成功，你將繼續強化過程；否則你將重新輸入一個密碼。</p><p>但是，如果你不想要此功能（我不會），只需按回車或任何其他鍵即可跳過使用它。</p><p>對於其他選項，我建議開啓它們（對於每一步輸入 <code>y</code> 或者 <code>Y</code> 和按下回車）。它們（依序）是：“<ruby>移除匿名用户<rt>remove anonymous user</rt></ruby>”，“<ruby>禁止 root 遠程登錄<rt>disallow root login remotely</rt></ruby>”，“<ruby>移除測試資料庫及其訪問<rt>remove test database and access to it</rt></ruby>”。“<ruby>重新載入權限表<rt>reload privilege tables now</rt></ruby>”。</p><h4 id="鏈接與斷開-mysql-server" tabindex="-1">鏈接與斷開 MySQL Server <a class="header-anchor" href="#鏈接與斷開-mysql-server" aria-label="Permalink to “鏈接與斷開 MySQL Server”">​</a></h4><p>為了運行 SQL 查詢，你首先必須使用 MySQL 連到服務器並在 MySQL 提示符使用。</p><p>執行此操作的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysql -h host_name -u user -p</span></span></code></pre></div><ul><li><code>-h</code> 用來指定一個主機名（如果這個服務被安裝到其他機器上，那麼會有用；如果沒有，忽略它）</li><li><code>-u</code> 指定登錄的用户</li><li><code>-p</code> 指定你想輸入的密碼.</li></ul><p>雖然出於安全原因不建議，但是你可以在命令列最右邊的 <code>-p</code> 後直接輸入密碼。例如，如果用户<code>test_user</code> 的密碼是 <code>1234</code>，那麼你可以在你使用的機器上嘗試去連接，你可以這樣使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysql -u test_user -p1234</span></span></code></pre></div><p>如果你成功輸入了必要的參數，你將會收到由 MySQL shell 提示符提供的歡迎（<code>mysql &gt;</code>）：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/04/mysql_shell_prompt-2.jpg?fit=800%2C423&amp;ssl=1" alt=""></p><p>要從服務端斷開連接和離開 MySQL 提示符，輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>QUIT</span></span></code></pre></div><p>輸入 <code>quit</code> （MySQL 不區分大小寫）或者 <code>\\q</code> 也能工作。按下回車退出。</p><p>你使用簡單的命令也能輸出關於版本的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mysqladmin -u root version -p</span></span></code></pre></div><p>如果你想看命令列選項列表，使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mysql --help</span></span></code></pre></div><h4 id="卸載-mysql" tabindex="-1">卸載 MySQL <a class="header-anchor" href="#卸載-mysql" aria-label="Permalink to “卸載 MySQL”">​</a></h4><p>如果您決定要使用較新版本或只是想停止使用 MySQL。</p><p>首先，關閉服務：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl stop mysql.service &amp;&amp; sudo systemctl disable mysql.service</span></span></code></pre></div><p>確保你備份了你的資料庫，以防你之後想使用它們。你可以通過運行下列命令卸載 MySQL：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt purge mysql*</span></span></code></pre></div><p>清理依賴：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt autoremove</span></span></code></pre></div><h3 id="小結" tabindex="-1">小結 <a class="header-anchor" href="#小結" aria-label="Permalink to “小結”">​</a></h3><p>在這篇文章中，我已經介紹如何在 Ubuntu Linux 上安裝 Mysql。我很高興如果這篇文章能幫助到那些正為此掙扎的用户或者剛剛開始的用户。</p><p>如果你發現這篇文章是一個很有用的資源，在評論裏告訴我們。你為了什麼使用 MySQL? 我們渴望收到你的任何反饋、印象和建議。感謝閲讀，並毫不猶豫地嘗試這個很棒的工具！</p><hr>',48)),t("p",null,[s[14]||(s[14]=i("via: ",-1)),a(e,{href:"https://itsfoss.com/install-mysql-ubuntu/"},{default:l(()=>[...s[13]||(s[13]=[i("https://itsfoss.com/install-mysql-ubuntu/",-1)])]),_:1})]),t("p",null,[s[19]||(s[19]=i("作者：",-1)),a(e,{href:"https://itsfoss.com/author/sergiu/"},{default:l(()=>[...s[15]||(s[15]=[i("Sergiu",-1)])]),_:1}),s[20]||(s[20]=i(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[16]||(s[16]=[i("lujun9972",-1)])]),_:1}),s[21]||(s[21]=i(" 譯者：",-1)),a(e,{href:"https://github.com/arrowfeng"},{default:l(()=>[...s[17]||(s[17]=[i("arrowfeng",-1)])]),_:1}),s[22]||(s[22]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:l(()=>[...s[18]||(s[18]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[25]||(s[25]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[23]||(s[23]=[i("LCTT",-1)])]),_:1}),s[26]||(s[26]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:l(()=>[...s[24]||(s[24]=[i("Linux中國",-1)])]),_:1}),s[27]||(s[27]=i(" 榮譽推出",-1))])])}const S=p(u,[["render",h]]);export{L as __pageData,S as default};
